function mostPalindromePieces(s: string, k: number): number {
  const n = s.length;
  // pal[j][i]: s[j..i] inclusive is a palindrome
  const pal: boolean[][] = Array.from({ length: n }, () => new Array(n).fill(false));
  for (let i = 0; i < n; i++) {
    for (let j = i; j >= 0; j--) {
      pal[j][i] = s[j] === s[i] && (i - j < 2 || pal[j + 1][i - 1]);
    }
  }
  const best = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    best[i] = best[i - 1];
    for (let j = i - k; j >= 0; j--) {
      if (pal[j][i - 1]) best[i] = Math.max(best[i], best[j] + 1);
    }
  }
  return best[n];
}

