function mostPalindromePieces(s: string, k: number): number {
  const isPal = (lo: number, hi: number): boolean => {
    while (lo < hi) if (s[lo++] !== s[hi--]) return false;
    return true;
  };
  let free = 0, count = 0;
  for (let i = 0; i < s.length; i++) {
    if ((i - k + 1 >= free && isPal(i - k + 1, i)) || (i - k >= free && isPal(i - k, i))) {
      count++;
      free = i + 1;
    }
  }
  return count;
}

